/* Public release profile. This deterministic weather-shaped year is an explicit planning
   assumption, not project metering and not a substitute for a bankable energy-yield study. */
const PUBLIC_PROFILE_NOTE='Illustrative deterministic planning profile; not project metering.';
const PUBLIC_PROFILES=(()=>{
 const w=[],s=[],month=[]; let sw=0,ss=0,m=0,md=0;
 const clamp=(v,lo,hi)=>Math.max(lo,Math.min(hi,v));
 for(let d=0;d<365;d++){
  while(d>=md+DAYS[m]){md+=DAYS[m];m++;}
  const season=Math.cos(2*Math.PI*(d-15)/365);
  const daylight=12+4.15*Math.sin(2*Math.PI*(d-80)/365);
  const sunrise=12-daylight/2;
  const synoptic=0.095*Math.sin(2*Math.PI*d/8.7)+0.065*Math.sin(2*Math.PI*(d+17)/21.3)+0.035*Math.cos(2*Math.PI*d/3.9);
  const cloud=clamp(0.78+0.13*Math.sin(2*Math.PI*(d+9)/11.7)+0.08*Math.cos(2*Math.PI*d/27.1),0.34,0.98);
  for(let h=0;h<24;h++){
   const sunPhase=(h+0.5-sunrise)/daylight;
   const solar=sunPhase>0&&sunPhase<1?Math.pow(Math.sin(Math.PI*sunPhase),1.36)*cloud:0;
   const wind=clamp(0.255+0.055*season+synoptic+0.025*Math.cos(2*Math.PI*(h-3)/24)+0.018*Math.sin(2*Math.PI*(d*24+h)/61),0.015,0.92);
   w.push(wind);s.push(solar);month.push(m);sw+=wind;ss+=solar;
  }
 }
 const wm=sw/w.length,sm=ss/s.length;
 return {w,s,wUnit:w.map(v=>v/wm),sUnit:s.map(v=>v/sm),month,window:'Illustrative planning year',note:PUBLIC_PROFILE_NOTE};
})();


