   const rev=op?(ppaOn?(a.contr*prod*a.ppa+(1-a.contr)*prod*merch):(prod*tailP))/1e6:0;
   const gridFeeM=op?prod*(a.gridFee||0)*esc/1e6:0; // direct private line → no public-grid use-of-system charge (default 0, shown so it's audited as nil)
   const opex=(op?a.opexPerMW*a.mw*esc:0)+gridFeeM;
