 const debtAtCod=(rows.find(r=>r.y===cod)||{debt:debt}).debt+(rows.find(r=>r.y===cod)||{repay:0}).repay;
 const idc=Math.max(0,debtAtCod-debt), gearEff=totalCapex>0?debtAtCod/(totalCapex+idc):mac.gearing;
