 const usable=energy*b.rte; const perKW=b.capexPerKWh*b.durationH; const opex=cellCapex*b.opexPct;
 const energy10=energy*Math.pow(1-b.degr,10);
 // arbitrage from the real daily wholesale curve: charge the cheapest hours, discharge the priciest, full RTE on the way out.
 // As duration rises you buy/sell over more hours, so the captured spread shrinks (that is why longer duration lowers the return).
 const ph=(PRICES.per_year[b.priceYear]||PRICES.per_year['2025']).ph;
 const effDur=b.durationH*(1-(b.socFloor||0)); // SoC floor reserved as outage ride-through, not tradeable
 const nCh=Math.min(12,Math.max(0,effDur*b.cyclesDay)); // preserve fractional tradeable duration; e.g. 2 h with a 10% reserve models 1.8 h, not 1 h
 /* Buy and sell prices come from the day-by-day backtest, not from an average day. Averaging 365
    days into one flattens exactly the volatility the battery monetises, so the old average-day
    curve understated the capture. These are the volume-weighted prices the optimiser actually
    paid and received running every real day of the chosen year at the chosen duration, which is
    the same run that draws the Spreads tab. The average-day curve still drives the dispatch
    picture, because that is an illustration of when it charges, not of what it earns. */
 const _spY=(SPREAD.byDurYear[String(spreadDur())]||SPREAD.byDurYear['8']);
 const _spR=_spY.find(r=>String(r.y)===String(b.priceYear))||_spY[_spY.length-1];
 const sumBuy=nCh*_spR.buy, sumSell=nCh*_spR.sell, cf=(b.captureFactor||1);
 // behind-the-meter self-charge: renewable output above DC firm load spills into the battery at btmCharge (€/MWh; default 0 = curtailed/export-banned spill is free)
 // how much of the charging is met free from renewable output above the data center load. Read off the
 // planning year hour by hour, not off an average day: an average day hides the peaks, so the
 // old version always returned zero and priced every megawatt-hour of charging at the market.
 const _SS=(typeof supplyStats==='function')?supplyStats():null;
 const surplusDay=_SS?_SS.battIn/365:0;   // MWh/day the battery actually absorbs from spill
 const chargeDay=nCh*b.powerMW, fSelf=chargeDay>0?Math.min(1,surplusDay/chargeDay):0; // share of charging met free from spill
