function fmt(x,d=1){if(x==null||isNaN(x))return '-';return x.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});}
function pct(x,d=1){return (x*100).toFixed(d)+'%';}
function avg(a){return a.reduce((x,y)=>x+y,0)/a.length;}
function annPay(bal0,r,n){return (r>0&&n>0)?bal0*r/(1-Math.pow(1+r,-n)):(n>0?bal0/n:0);} // level debt service (annuity), reduces to flat principal at r=0
