/* ---- scenarios ----------------------------------------------------------------------------
   A scenario is the whole model state under a name. Saved in the tab's own storage, so it does
   not follow anyone around, and exportable to a file or a link for when it should. ---------- */
function snapshot(){return {version:2,model:JSON.parse(JSON.stringify(M)),tranche:JSON.parse(JSON.stringify(TRANCHE))};}
const MODEL_SCHEMA=JSON.parse(DEFAULTS_JSON);
const TRANCHE_SCHEMA=JSON.parse(DEFAULT_TRANCHE_JSON);
const UNIT_FIELDS=new Set(['infl','tax','gearing','grossCF','loss','lineLoss','rte','degr','socFloor','compression','contr','curtail','spvMargin','beMargin','claimShare','partPct','opexPct']);
const ENUM_FIELDS={
 'macro.amort':new Set(['flat','annuity']),
 'dc.marginMode':new Set(['pct','flat']),
 'dc.spvMode':new Set(['pass','fixed']),
 'dc.srcMode':new Set(['fixed','dayahead']),
 'dc.resMode':new Set(['ppa','lcoe'])
};
function modelNumberOK(path,v){
 if(typeof v!=='number'||!Number.isFinite(v))return false;
 const k=path.split('.').pop();
 if(UNIT_FIELDS.has(k))return v>=0&&v<=1;
 if(k==='feeEsc')return v>=0&&v<=0.30;
 if(k==='allInRate'||k==='debtRate')return v>=0&&v<=0.50;
 if(k==='dcac')return v>=0.5&&v<=3;
 if(k==='captureFactor')return v>=0.5&&v<=3;
 if(k==='mw'||k==='powerMW'||k==='firmMW')return v>=0&&v<=5000;
 if(k==='durationH')return [2,4,6,8].includes(v);
 if(k==='cyclesDay')return v>=0&&v<=4;
 if(k==='codY'||k==='gridYear')return Number.isInteger(v)&&v>=2026&&v<=2100;
 if(/(?:TermY|lifeY|tenor|leaseY)$/.test(k))return Number.isInteger(v)&&v>=0&&v<=60;
 return v>=0&&v<=1e6;
}
function cleanModel(src,shape,path=''){
 if(!src||typeof src!=='object'||Array.isArray(src))return null;
 const out=JSON.parse(JSON.stringify(shape));
 for(const k of Object.keys(shape)){
  if(!Object.prototype.hasOwnProperty.call(src,k))continue;
  const v=src[k], t=shape[k], p=path?path+'.'+k:k;
  if(typeof t==='number'){if(modelNumberOK(p,v))out[k]=v;}
  else if(typeof t==='boolean'){if(typeof v==='boolean')out[k]=v;}
  else if(typeof t==='string'){
   const allowed=ENUM_FIELDS[p];
   if(typeof v==='string'&&v.length<=40&&/^[A-Za-z0-9_.:-]+$/.test(v)&&(!allowed||allowed.has(v)))out[k]=v;
  }
  else if(t&&typeof t==='object'){const child=cleanModel(v,t,p);if(child)out[k]=child;}
 }
 return out;
}
function restore(s){
 const packet=(s&&s.version===2&&s.model)?s:{model:s,tranche:null};
 const clean=cleanModel(packet.model,MODEL_SCHEMA); if(!clean)return false;
 for(const k of Object.keys(M))if(Object.prototype.hasOwnProperty.call(clean,k))M[k]=clean[k];
 if(packet.tranche){
  const tr=cleanModel(packet.tranche,TRANCHE_SCHEMA,'tranche');
  if(tr)for(const k of Object.keys(TRANCHE))if(Object.prototype.hasOwnProperty.call(tr,k))TRANCHE[k]=tr[k];
 }
 _SUPC=null;_CLIPF=null;return true;
}
function htmlEsc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function safeScenName(v){
 const n=String(v||'').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,80);
 return /^(?:__proto__|prototype|constructor)$/i.test(n)?'':n;
}
function scenList(){
 try{
  const raw=JSON.parse(sessionStorage.getItem('gdcScen')||'{}'), out=Object.create(null);
  if(!raw||typeof raw!=='object'||Array.isArray(raw))return out;
  for(const k of Object.keys(raw).slice(0,40)){const n=safeScenName(k),v=raw[k];if(n&&v&&typeof v==='object')out[n]={t:Number.isFinite(v.t)?v.t:0,m:v.m};}
  return out;
 }catch(e){return Object.create(null);}
}
