function computeBatteryFin(){
 // Costs, debt service and the optional data-center capacity charge run from COD; merchant arbitrage and ancillary revenues start only in gridYear.
 const b=M.battery,B=computeBattery(b),mac=M.macro,allIn=(b.debtRate||mac.allInRate),g=(b.gearing!=null?b.gearing:mac.gearing),gy=b.gridYear,comp=b.compression,infl=mac.infl,bdeg=b.degr;
 const life=b.lifeY||25, endY=COD+life, btenor=Math.min(mac.tenor,Math.max(1,endY-(COD+1))), depY=Math.min(15,Math.max(1,endY-(COD+1)));
 const capex=B.capex; let bal=0,nol=0,ppy=0,annDS=0; const rows=[];
 for(let y=Y0;y<=YN;y++){
  let rev=0,opex=0,int=0,t=0,repay=0,fcfe=0;
  if(y===COD){const draw=g*capex;bal=draw;fcfe=-capex+draw;}
  else if(y>COD&&y<endY){
   const k=Math.max(0,y-gy);
   const merch=(y>=gy)?(B.arbRev*Math.pow(1-bdeg,k)+B.ancRev)*Math.pow(1-comp,k)*Math.pow(1+infl,k):0;
   const capR=(B.capRev||0)*Math.pow(1+infl,y-(COD+1));
   rev=merch+capR;
   opex=B.opex*Math.pow(1+infl,y-2023)+((y>=gy)?B.gridFee*feeF(y):0);
   if(ppy===0){ppy=bal/btenor;annDS=annPay(bal,allIn,btenor);} int=bal*allIn;
   const dep=(y<=COD+depY)?capex/depY:0; const ebt=rev-opex-dep-int; let tb=ebt+nol; if(tb>0){t=tb*mac.tax;nol=0;}else{nol=tb;}
   repay=(y<=COD+btenor)?Math.min(bal,mac.amort==='annuity'?annDS-int:ppy):0; bal-=repay; if(Math.abs(bal)<1e-9)bal=0; fcfe=rev-opex-t-repay-int;
  }
  rows.push({y,rev,opex,int,repay,tax:t,ebitda:rev-opex,fcfe});
 }
 const irr=xirr(rows.map(r=>r.fcfe),rows.map(r=>r.y+0.99));
 // equity = the cash actually injected, not the gearing formula. Construction equity plus every
 // operating year the battery cannot cover its own debt service (it earns only the reliability fee until gridYear).
 const eqCash=-rows.filter(r=>r.fcfe<0).reduce((s,r)=>s+r.fcfe,0);
 const eqForm=(1-g)*capex;
 return{rows,irr,equity:eqCash,equityAtCod:eqForm,standby:Math.max(0,eqCash-eqForm),debt:g*capex,capex};
}
function drawBatteryCharts(){
 const b=M.battery,B=computeBattery(b),hrs=[...Array(24).keys()];
 const price=(PRICES.per_year[b.priceYear]||PRICES.per_year['2025']).ph;
 const powMW=b.powerMW, energyMWh=b.powerMW*b.durationH, rte=b.rte, dur=b.durationH, cyc=b.cyclesDay;
 // charge the cheapest hours, discharge the priciest, on the real wholesale price curve. Full RTE loss on the exit side.
 const reserve=(b.socFloor||0)*energyMWh; // outage ride-through reserve, never traded
 const nCh=B.nCh, nSlots=Math.ceil(nCh), part=nSlots?Math.max(0,nCh-Math.floor(nCh)):0;
 const order=hrs.slice().sort((x,y)=>price[x]-price[y]);
 const weights=list=>new Map(list.map((h,i)=>[h,(i===nSlots-1&&part>1e-9)?part:1]));
 const chg=weights(order.slice(0,nSlots)), dis=weights(order.slice(24-nSlots));
 let soc=reserve,drawn=0,deliv=0; const act=[],socP=[],col=[],txt=[];
 for(let h=0;h<24;h++){let a=0;
   if(chg.has(h)&&soc<energyMWh-1e-6){a=Math.min(powMW*chg.get(h),energyMWh-soc);soc+=a;drawn+=a;col.push('#43c079');txt.push('Charge @ €'+fmt(price[h],0));}
   else if(dis.has(h)&&soc>reserve+1e-6){const out=Math.min(powMW*dis.get(h),(soc-reserve)*rte);soc-=out/rte;a=-out;deliv+=out;col.push('#ff6b6b');txt.push('Discharge @ €'+fmt(price[h],0));}
   else{col.push('#39465a');txt.push('Idle @ €'+fmt(price[h],0));}
   act.push(a);socP.push(energyMWh>0?soc/energyMWh*100:0);}
 const lossPct=drawn>0?(1-deliv/drawn)*100:0, maxP=Math.max(...price)*1.05;
 Plotly.react('bch_disp',[
   {x:hrs,y:act.map((a,i)=>a>0?a:null),name:'Charging',type:'bar',marker:{color:'#43c079'},customdata:txt,hovertemplate:'%{customdata}: %{y:,.0f} MW<extra></extra>'},
   {x:hrs,y:act.map((a,i)=>a<0?a:null),name:'Discharging',type:'bar',marker:{color:'#ff6b6b'},customdata:txt,hovertemplate:'%{customdata}: %{y:,.0f} MW<extra></extra>'},
   {x:hrs,y:act.map((a,i)=>a===0?0:null),name:'Idle',type:'bar',marker:{color:'#39465a'},customdata:txt,hovertemplate:'%{customdata}<extra></extra>'},
   {x:hrs,y:price,name:'Wholesale price',type:'scatter',yaxis:'y2',line:{color:'#ffb23e',dash:'dot',width:2},hovertemplate:'€%{y:,.0f}/MWh<extra></extra>'},
   {x:hrs,y:socP.map(s=>s/100*maxP),name:'State of charge',type:'scatter',yaxis:'y2',line:{color:'#b98cff',width:2.4},customdata:socP,hovertemplate:'SoC %{customdata:,.0f}%<extra></extra>'}
 ],lay('Dispatch on the '+b.priceYear+' curve',
   {showlegend:true,xaxis:{dtick:2,gridcolor:'#2b3644'},yaxis:{title:{text:'MW',font:{size:12}}},
    yaxis2:{overlaying:'y',side:'right',range:[0,maxP],title:{text:'€/MWh · SoC scaled',font:{size:11.5},standoff:14},gridcolor:'transparent'},margin:{r:76}}),CFG);
 const F=computeBatteryFin(), fr=F.rows.filter(r=>r.y>=COD&&r.y<COD+(M.battery.lifeY||25)), fyrs=fr.map(r=>r.y), Zb=assetRanges();
 Plotly.react('bch_econ',[
   {x:fyrs,y:fr.map(r=>r.fcfe),name:'Equity cash flow',type:'bar',marker:{color:fr.map(r=>r.fcfe>=0?'#43c079':'#ff6b6b')},hovertemplate:HT('€m')}
 ],lay('Battery equity cash flow',{barmode:'relative',showlegend:true,yaxis:{range:[Zb.fcfeMin,Zb.fcfeMax],title:{text:'€m',font:{size:12}},gridcolor:'#2b3644'}}),CFG);
}
