/* Headroom uses the same public normalized planning profile as the supply model. */
function clipSeries(){return {w:PUBLIC_PROFILES.wUnit,s:PUBLIC_PROFILES.sUnit};}
function headroom(){
 const T=clipSeries(), a=M.wind, b=M.solar, cap=M.dc.firmMW;
 const wOn=a.on!==false, sOn=b.on!==false;
 const wk=wOn?effCF(a)*a.mw:0, sk=sOn?effCF(b)*b.mw:0;
 const v=T.w.map((x,i)=>x*wk+T.s[i]*sk).sort((x,y)=>y-x);
 const n=v.length, at=p=>v[Math.min(n-1,Math.floor(p/100*n))];
 return {v,n,peak:v[0],p01:at(0.01),p1:at(1),p5:at(5),
   overCap:v.filter(x=>x>cap).length, overPct:v.filter(x=>x>cap).length/n*100,
   energyOver:v.reduce((s2,x)=>s2+Math.max(0,x-cap),0)*0.25/ (n*0.25/8760) /1000,   // GWh a year above the cap
   nameplate:(wOn?a.mw:0)+(sOn?b.mw:0), cap};
}
