function availYear(s){const m=/(20\d{2})/.exec(s||'');if(m)return +m[1];const q=/'(\d{2})/.exec(s||'');return q?2000+ +q[1]:2099;}

/* ================== the Nickelsdorf scene ==================
   Golden hour on the Pannonian plain, one full turn of the day in 108 seconds.
   One SVG, no external assets. The machines are drawn to their real proportions: a 150 m
   rotor on a 105 m tower, single-axis trackers on a north-south torque tube, three data
   halls, the private line running in from the parks, and the Neusiedler See on the horizon. */
const SCN={cycle:108,t0:14};
function reduceMo(){try{return window.matchMedia('(prefers-reduced-motion: reduce)').matches;}catch(e){return false;}}

/* one blade, root at the origin, pointing up: narrow root, widest near a quarter span,
   slim swept tip. That planform is what makes a turbine read as a turbine. */
function bladePath(R){
 const cR=0.056*R, cM=0.092*R, cT=0.018*R, sw=0.050*R;
 return `M ${-cR*0.55},${-0.024*R}
   C ${-cM*0.92},${-0.155*R} ${-cM},${-0.285*R} ${-cM*0.84+sw*0.25},${-0.45*R}
   C ${-cM*0.58+sw*0.55},${-0.65*R} ${-cT*1.6+sw*0.9},${-0.86*R} ${-cT*0.5+sw},${-0.975*R}
   Q ${sw+cT*0.1},${-1.006*R} ${cT*0.9+sw},${-0.972*R}
   C ${cT*2.2+sw*0.85},${-0.84*R} ${cM*0.40+sw*0.5},${-0.61*R} ${cM*0.58+sw*0.2},${-0.41*R}
   C ${cM*0.70},${-0.245*R} ${cR*0.85},${-0.105*R} ${cR*0.62},${-0.016*R} Z`;
}
function rotorDef(id,R,dur,phase,mo,fill,rim){
 const b=bladePath(R);
 const one=a=>`<g transform="rotate(${a})"><path d="${b}" fill="${fill}"/>`+
   (rim?`<path d="${b}" fill="${rim}" opacity=".13" transform="translate(${-0.014*R},0) scale(0.22,1)"/>`:'')+`</g>`;
 const spin=mo?'':`<animateTransform attributeName="transform" attributeType="XML" type="rotate"
     from="0 0 0" to="360 0 0" dur="${dur}s" begin="${-phase}s" repeatCount="indefinite"/>`;
 return `<g id="${id}">
   <g>${spin}${one(0)}${one(120)}${one(240)}</g>
   <circle r="${0.030*R}" fill="${fill}"/></g>`;
}
/* a turbine silhouette: tapered tower, nacelle, rotor reused from defs */
function turbine(x,gy,s,rotor,fill,rim){
 const R=100*s, hubY=gy-1.42*R, tw=0.060*R, bw=0.130*R;
 return `<g>
  <path d="M${x-bw},${gy} L${x-tw*0.5},${hubY+0.02*R} L${x+tw*0.5},${hubY+0.02*R} L${x+bw},${gy} Z" fill="${fill}"/>
  ${rim?`<path d="M${x+bw*0.30},${gy} L${x+tw*0.16},${hubY+0.02*R} L${x+tw*0.44},${hubY+0.02*R} L${x+bw*0.86},${gy} Z" fill="${rim}" opacity=".55"/>`:''}
  <path d="M${x+0.018*R},${hubY-0.048*R} L${x+0.158*R},${hubY-0.036*R} Q ${x+0.190*R},${hubY} ${x+0.158*R},${hubY+0.036*R}
           L${x+0.018*R},${hubY+0.048*R} Z" fill="${fill}"/>
  ${rim?`<path d="M${x+0.018*R},${hubY-0.048*R} L${x+0.158*R},${hubY-0.036*R} Q ${x+0.190*R},${hubY} ${x+0.158*R},${hubY+0.036*R}"
        fill="none" stroke="${rim}" stroke-width="${0.009*R}" opacity=".8"/>`:''}
  <circle cx="${x+0.144*R}" cy="${hubY-0.050*R}" r="${0.017*R}" fill="#ff5252" class="beacon"/>
  <use href="#${rotor}" transform="translate(${x},${hubY}) scale(${s})"/>
 </g>`;
}
/* single-axis trackers: a see-saw about the torque tube is exactly what one does */
function trackerDef(id,mo,fill,rim){
 const T=SCN.cycle, B=-SCN.t0;
 const tilt=mo?'transform="rotate(28)"':'';
 const anim=mo?'':`<animateTransform attributeName="transform" attributeType="XML" type="rotate"
    values="44;44;28;0;-28;-44;-44;44" keyTimes="0;0.14;0.24;0.37;0.50;0.60;0.72;1"
    dur="${T}s" begin="${B}s" repeatCount="indefinite"/>`;
 return `<g id="${id}">
   <line x1="0" y1="0" x2="0" y2="9" stroke="${fill}" stroke-width="1.6"/>
   <g ${tilt}>${anim}
     <rect x="-13" y="-2.3" width="26" height="4.6" rx="0.7" fill="${fill}"/>
     <line x1="-13" y1="-2.3" x2="13" y2="-2.3" stroke="${rim}" stroke-width="1.15" opacity="1"/>
     <line x1="-13" y1="2.3" x2="13" y2="2.3" stroke="${rim}" stroke-width=".55" opacity=".3"/>
   </g></g>`;
}
function trackerBand(ref,x0,y0,w,rows,s,squash,step){
 const out=[];
 for(let r=0;r<rows;r++){
  const t=rows>1?r/(rows-1):1, sc=s*(0.70+0.30*t), y=y0+r*(step||18)*(0.6+0.6*t), inset=w*0.04*(1-t);
  const gap=36*sc, n=Math.max(2,Math.floor((w-2*inset)/gap)), row=[];
  for(let i=0;i<n;i++){
   if(i%6===5) continue;                                   // access corridor between blocks
   row.push(`<use href="#${ref}" transform="translate(${(x0+inset+i*gap+gap*0.5).toFixed(1)},${y.toFixed(1)}) scale(${sc.toFixed(3)})"/>`);
  }
  out.push(row.join(''));
 }
 return `<g transform="translate(0,${y0}) scale(1,${squash}) translate(0,${-y0})">${out.join('')}</g>`;
}
function pylon(x,y,s,span,fill){
 const H=52*s, a1=15*s, a2=11*s, lat=[];
 for(let i=0;i<6;i++){const t=i/6,u=(i+1)/6, w1=7*s*(1-t*0.64), w2=7*s*(1-u*0.64);
  lat.push(`<path d="M${x-w1},${y-H*t} L${x+w2},${y-H*u} M${x+w1},${y-H*t} L${x-w2},${y-H*u}"
    stroke="${fill}" stroke-width="${0.55*s}" fill="none"/>`);}
 const cond=span?`<path d="M${x-a1},${y-H+2.6*s} Q${x+span/2},${y-H+2.6*s+9*s} ${x+span-a1},${y-H+2.6*s}"
     stroke="${fill}" stroke-width="${0.65*s}" fill="none" opacity=".8"/>
   <path d="M${x-a2},${y-H+10*s} Q${x+span/2},${y-H+10*s+9.6*s} ${x+span-a2},${y-H+10*s}"
     stroke="${fill}" stroke-width="${0.6*s}" fill="none" opacity=".7"/>`:'';
 return `<g>${cond}
   <path d="M${x-7*s},${y} L${x-2.5*s},${y-H} L${x+2.5*s},${y-H} L${x+7*s},${y} Z" fill="none" stroke="${fill}" stroke-width="${0.85*s}"/>
   ${lat.join('')}
   <line x1="${x-a1}" y1="${y-H+2.6*s}" x2="${x+a1}" y2="${y-H+2.6*s}" stroke="${fill}" stroke-width="${1*s}"/>
   <line x1="${x-a2}" y1="${y-H+10*s}" x2="${x+a2}" y2="${y-H+10*s}" stroke="${fill}" stroke-width="${0.9*s}"/></g>`;
}
function hall(x,y,w,d,hgt,fill,rim,lit){
 const louv=Array.from({length:Math.max(2,Math.floor(w/11))},(_,i)=>
   `<rect x="${x+5+i*11}" y="${y+hgt*0.50}" width="6" height="${hgt*0.28}" rx="1" fill="#000" opacity=".45"/>`).join('');
 const win=Array.from({length:Math.max(2,Math.floor(w/18))},(_,i)=>
   `<rect x="${x+7+i*18}" y="${y+hgt*0.18}" width="9" height="5" rx="1.2" fill="${lit}" opacity=".22" class="glowWin"/>`).join('');
 const cool=Array.from({length:3},(_,i)=>{const cx=x+d*0.5+w*0.20+i*w*0.28, cy=y-d*0.58+2.5;
   return `<rect x="${cx-7}" y="${cy-6.5}" width="14" height="7" rx="1.5" fill="${fill}"/>`;}).join('');
 return `<g>
   <path d="M${x},${y} L${x+d},${y-d*0.58} L${x+w+d},${y-d*0.58} L${x+w},${y} Z" fill="${fill}"/>
   <path d="M${x},${y} L${x+d},${y-d*0.58} L${x+w+d},${y-d*0.58}" fill="none" stroke="${rim}" stroke-width="1.1" opacity=".75"/>
   ${cool}
   <rect x="${x}" y="${y}" width="${w}" height="${hgt}" fill="${fill}"/>
   <line x1="${x+w}" y1="${y}" x2="${x+w}" y2="${y+hgt}" stroke="${rim}" stroke-width="1" opacity=".5"/>
   ${louv}${win}</g>`;
}

/* a working tower crane: lattice mast, jib with counterweight, a trolley that travels the jib
   and a hook that rises and falls. The Abilene look: steel going up next to finished halls. */

/* ============ 14 · LANDING SCENE, SPLASH & OVERVIEW ============ */
function crane(x,gy,s,col,ph,mo){
 const mh=118*s, topY=gy-mh, jib=104*s, cjib=30*s, ty=topY-7*s;
 let lat='';
 for(let i=0;i<8;i++){const y1=gy-i*mh/8,y2=gy-(i+1)*mh/8;
  lat+=`<path d="M${(x-3.1*s).toFixed(1)},${y1.toFixed(1)} L${(x+3.1*s).toFixed(1)},${y2.toFixed(1)} M${(x+3.1*s).toFixed(1)},${y1.toFixed(1)} L${(x-3.1*s).toFixed(1)},${y2.toFixed(1)}" stroke="${col}" stroke-width="${(0.7*s).toFixed(2)}" fill="none"/>`;}
 const trolley=mo?'':`<animateTransform attributeName="transform" type="translate" values="0 0;${-jib*0.42} 0;${-jib*0.42} 0;${jib*0.06} 0;0 0" keyTimes="0;0.3;0.5;0.82;1" dur="${44+ph*6}s" begin="${-ph*9}s" repeatCount="indefinite"/>`;
 const hookLen=26*s;
 return `<g>
  <path d="M${x-4.6*s},${gy} L${x-3.1*s},${topY} M${x+4.6*s},${gy} L${x+3.1*s},${topY}" stroke="${col}" stroke-width="${1.1*s}"/>
  ${lat}
  <path d="M${x},${topY-15*s} L${x+jib},${ty} M${x},${topY-15*s} L${x-cjib},${ty}" stroke="${col}" stroke-width="${0.8*s}"/>
  <path d="M${x-cjib},${ty} L${x+jib},${ty}" stroke="${col}" stroke-width="${1.3*s}"/>
  <rect x="${x-cjib}" y="${ty}" width="${9*s}" height="${5.5*s}" fill="${col}"/>
  <rect x="${x-3*s}" y="${topY-4*s}" width="${7.5*s}" height="${5.5*s}" fill="${col}"/>
  <g transform="translate(${x+jib*0.78},0)">${trolley}
    <rect x="${-2.4*s}" y="${ty}" width="${4.8*s}" height="${2.6*s}" fill="${col}"/>
    <line x1="0" y1="${ty+2.6*s}" x2="0" y2="${ty+hookLen}" stroke="${col}" stroke-width="${0.6*s}"/>
    <path d="M${-2.6*s},${ty+hookLen} l ${5.2*s} 0 l 0 ${3.4*s} l ${-5.2*s} 0 Z" fill="${col}"/>
  </g>
  <circle cx="${x}" cy="${topY-16.5*s}" r="${1.7*s}" fill="#ff5252" class="beacon"/>
 </g>`;
}
/* a hall still in steel: columns, roof line, cross bracing, no walls yet */
function frameHall(x,y,w,d,hgt,col){
 const n=Math.max(4,Math.floor(w/15));
 let posts='';
 for(let i=0;i<=n;i++){const cx=x+i*w/n;
  posts+=`<line x1="${cx.toFixed(1)}" y1="${y}" x2="${cx.toFixed(1)}" y2="${y+hgt}" stroke="${col}" stroke-width="1.1"/>`;}
 return `<g opacity=".95">
  <path d="M${x},${y} L${x+d},${y-d*0.58} L${x+w+d},${y-d*0.58} L${x+w},${y}" fill="none" stroke="${col}" stroke-width="1.1"/>
  <line x1="${x}" y1="${y}" x2="${x+w}" y2="${y}" stroke="${col}" stroke-width="1.3"/>
  <line x1="${x}" y1="${y+hgt}" x2="${x+w}" y2="${y+hgt}" stroke="${col}" stroke-width="1.3"/>
  ${posts}
  <path d="M${x},${y+hgt} L${x+w/(Math.max(4,Math.floor(w/15)))},${y} M${x+w/(Math.max(4,Math.floor(w/15)))},${y+hgt} L${x},${y}" stroke="${col}" stroke-width=".7" opacity=".7"/>
  <line x1="${x+d*0.5}" y1="${y-d*0.29}" x2="${x+w+d*0.5}" y2="${y-d*0.29}" stroke="${col}" stroke-width=".6" opacity=".55"/>
 </g>`;
}
