function splashHTML(){
 const chip=(ci,ico,v,u,l)=>`<div class="sChip" style="--ci:${ci}"><span class="ic">${ico}</span>
   <span><span class="sv">${v}<small>${u}</small></span><span class="sl" style="display:block">${l}</span></span></div>`;
 return `<div id="splash" role="dialog" aria-modal="true" aria-labelledby="splashTitle">
  <div class="splashScene">${landingScene('scSplash',900,'sceneFill')}
   <div style="position:absolute;inset:0;background:radial-gradient(ellipse at 50% 42%,rgba(7,11,16,.34),rgba(7,11,16,.86))"></div></div>
  <div class="splashInner">
   <div class="splashKicker" style="display:flex;align-items:center;justify-content:center;gap:10px">${FLAG.at}<span>Burgenland · Austria</span></div>
   <h1 class="wmk splashWm" id="splashTitle"><span class="nk">Green Data Campus</span>Nickelsdorf</h1>
   <div class="splashRule"></div>
   <div class="splashStats">
    ${chip('#8ef0b8',SICO.dc,fmt(M.dc.firmMW,0),' MW','Data center')}
    ${chip('#4aa8ff',SICO.wind,fmt(M.wind.mw,0),' MW','Wind')}
    ${chip('#ffb23e',SICO.sun,fmt(M.solar.mw,0),' MWp','Solar')}
    ${chip('#b98cff',SICO.batt,fmt(M.battery.powerMW,0)+' MW',' · '+fmt(M.battery.durationH,0)+'h','Storage')}
    ${chip('#46b45a',SICO.line,'110',' kV','Private direct line')}
   </div>
   <button class="splashBtn" onclick="closeSplash()">Open dashboard<span class="arr">→</span></button>
  </div>
  <div class="splashFoot" aria-label="Planning scenario">
   <a class="brandLink splashPartner splashPartnerNx" href="https://nexwell.com" target="_blank" rel="noopener noreferrer" title="Nexwell">${NXLOGO('')}</a>
   <span style="color:#98a7b6;font-size:16px">×</span>
   <a class="brandLink splashPartner splashPartnerBe" href="https://www.burgenlandenergie.at" target="_blank" rel="noopener noreferrer" title="Burgenland Energie">${BELOGO('',true)}</a>
  </div>
 </div>`;
}
function closeSplash(){
 const s=document.getElementById('splash'); if(!s)return;
 s.classList.add('out');
 document.querySelectorAll('body>header,body>nav,body>main,body>footer').forEach(el=>el.inert=false);
 try{sessionStorage.setItem('gdcSplash','1');}catch(e){}
 setTimeout(()=>{s.remove();document.querySelector('header .wmHead')?.focus();},700);
}
function maybeSplash(){
 let seen=false; try{seen=sessionStorage.getItem('gdcSplash')==='1';}catch(e){}
 if(seen)return;
 document.body.insertAdjacentHTML('beforeend',splashHTML());
 document.querySelectorAll('body>header,body>nav,body>main,body>footer').forEach(el=>el.inert=true);
 setTimeout(()=>document.querySelector('#splash .splashBtn')?.focus(),0);
 document.addEventListener('keydown',function esc(e){if(e.key==='Escape'){closeSplash();document.removeEventListener('keydown',esc);}});
}

/* ---------------- the Overview page ---------------- */
/* a small inline sparkline. No chart library, so it stays crisp and costs nothing. */
function spark(vals,opt){
 const o=Object.assign({w:260,h:52,col:'#46b45a',fill:true,dot:true,pad:5},opt||{});
 const v=vals.filter(x=>x!=null&&!isNaN(x));
 if(v.length<2)return '';
 const mn=Math.min(...v), mx=Math.max(...v), rng=(mx-mn)||1;
 const X=i=>o.pad+i*(o.w-2*o.pad)/(v.length-1), Y=x=>o.h-o.pad-(x-mn)/rng*(o.h-2*o.pad);
 const pts=v.map((x,i)=>`${X(i).toFixed(1)},${Y(x).toFixed(1)}`).join(' ');
 const area=o.fill?`<polygon points="${o.pad},${o.h} ${pts} ${o.w-o.pad},${o.h}" fill="${o.col}" opacity=".12"/>`:'';
 const last=o.dot?`<circle cx="${X(v.length-1).toFixed(1)}" cy="${Y(v[v.length-1]).toFixed(1)}" r="3" fill="${o.col}"/>`:'';
 return `<svg class="spark" viewBox="0 0 ${o.w} ${o.h}" preserveAspectRatio="none" aria-hidden="true">
   ${area}<polyline points="${pts}" fill="none" stroke="${o.col}" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round"/>${last}</svg>`;
}

/* how the power moves: parks, private line, data center, storage, grid as backup only.
   Every node carries a small glyph and pops on hover; the electrons keep moving. */
function flowDiagram(){
 const W=1180,H=250, g='#009a44', gh='#46b45a', wind='#4aa8ff', sol='#ffb23e', bat='#b98cff',
       grid='#8fa3bb', line='#2c3a33', txt='#d7e2db', mut='#93a49a';
 const GLY={
  wind:`<g stroke="${wind}" stroke-width="1.7" fill="none" stroke-linecap="round"><path d="M11 11v8.5"/><path d="M8 19.5h6"/><path d="M11 11 5.2 8"/><path d="M11 11l5.8-3"/><path d="M11 11V4"/><circle cx="11" cy="11" r="1.4" fill="${wind}" stroke="none"/></g>`,
  sun:`<g stroke="${sol}" stroke-width="1.7" fill="none" stroke-linecap="round"><circle cx="11" cy="11" r="4"/><path d="M11 2.5v2M11 17.5v2M2.5 11h2M17.5 11h2M5 5l1.4 1.4M16 16l-1.4-1.4M17 5l-1.4 1.4M5 17l1.4-1.4"/></g>`,
  at:`<g><rect width="21" height="14" rx="1.6" fill="#fff"/><rect width="21" height="4.7" rx="1.6" fill="#ED2939"/><rect y="9.3" width="21" height="4.7" rx="1.6" fill="#ED2939"/></g>`,
  pylon:`<g stroke="${gh}" stroke-width="1.6" fill="none" stroke-linecap="round"><path d="M11 3v2.6"/><path d="M4.6 19.5 11 5.6l6.4 13.9"/><path d="M7.6 13.4h6.8"/><path d="M6.2 16.6h9.6"/><path d="M2 8.4h18"/><path d="M2 8.4q4.5 3 9 0t9 0" opacity=".55"/></g>`,
  batt:`<g stroke="${bat}" stroke-width="1.7" fill="none" stroke-linecap="round" stroke-linejoin="round"><rect x="2.5" y="6.5" width="15" height="9.5" rx="2"/><path d="M20 9.5v3.5"/><path d="M10.4 8.4 8 11.6h3l-2.1 2.8"/></g>`,
  dc:`<g stroke="#eaf2f8" stroke-width="1.7" fill="none" stroke-linecap="round"><rect x="2.5" y="4" width="17" height="5" rx="1.3"/><rect x="2.5" y="13" width="17" height="5" rx="1.3"/><path d="M5.6 6.5h.01M5.6 15.5h.01"/><path d="M9 6.5h7M9 15.5h7"/></g>`};
 const box=(x,y,w,hh,title,sub,col,accent,gly)=>`
   <g class="fNode"><rect x="${x}" y="${y}" width="${w}" height="${hh}" rx="11" fill="#1b2520" stroke="${col}" stroke-width="1.2"/>
   <rect x="${x}" y="${y}" width="3.5" height="${hh}" rx="1.8" fill="${accent||col}"/>
   ${gly?`<g transform="translate(${x+13},${y+(hh-22)/2}) scale(1)">${gly}</g>`:''}
   <text x="${x+(gly?42:16)}" y="${y+25}" font-size="15" font-weight="600" fill="${txt}" font-family="Inter,sans-serif">${title}</text>
   <text x="${x+(gly?42:16)}" y="${y+45}" font-size="12.5" fill="${mut}" font-family="Inter,sans-serif">${sub}</text></g>`;
 const flow=(d,col,dur,dash)=>`
   <path d="${d}" fill="none" stroke="${col}" stroke-width="1.6" opacity=".55"${dash?` stroke-dasharray="5 5"`:''}/>
   <circle r="3.1" fill="${col}"><animateMotion dur="${dur}s" repeatCount="indefinite" path="${d}"/></circle>
   <circle r="3.1" fill="${col}" opacity=".55"><animateMotion dur="${dur}s" begin="${dur/3}s" repeatCount="indefinite" path="${d}"/></circle>
   <circle r="3.1" fill="${col}" opacity=".3"><animateMotion dur="${dur}s" begin="${2*dur/3}s" repeatCount="indefinite" path="${d}"/></circle>`;
 return `<svg viewBox="0 0 ${W} ${H}" class="flowSVG" style="display:block;width:100%;height:auto" role="img"
   aria-label="Planning concept in which wind and solar connect through private lines, with storage and the public grid providing balancing services">
  <g class="fSeg fF-wind">${flow(`M262,58 C360,58 380,104 452,104`,wind,3.2)}</g>
  <g class="fSeg fF-sol">${flow(`M262,150 C360,150 380,110 452,110`,sol,3.8)}</g>
  <g class="fSeg fF-linedc">${flow(`M700,107 C760,107 790,107 858,107`,gh,2.9)}</g>
  <g class="fSeg fF-battc">${flow(`M576,150 C576,182 576,190 576,196`,bat,3.4)}</g>
  <g class="fSeg fF-battd">${flow(`M700,214 C790,214 830,150 858,132`,bat,4.2)}</g>
  <g class="fSeg fF-grid">${flow(`M262,220 C420,258 700,258 862,158`,grid,5.4,true)}</g>
  <g class="fSeg fN-wind">${box(28,32,234,52,`${fmt(M.wind.mw,0)} MW wind`,`illustrative planning zones`,line,wind,GLY.wind)}</g>
  <g class="fSeg fN-sol">${box(28,124,234,52,`${fmt(M.solar.mw,0)} MWp solar`,`trackers and agri-PV`,line,sol,GLY.sun)}</g>
  <g class="fSeg fN-grid">${box(28,188,234,52,'Austrian grid',`balance only · NE3 fees apply`,line,grid,GLY.at)}</g>
  <g class="fNode fSeg fN-line"><rect x="452" y="60" width="248" height="98" rx="11" fill="#16211c" stroke="${g}" stroke-width="1.4"/>
   <g transform="translate(468,72)">${GLY.pylon}</g>
   <text x="590" y="93" font-size="14.5" font-weight="640" fill="${txt}" text-anchor="middle" font-family="Inter,sans-serif">Private direct line</text>
   <text x="590" y="114" font-size="12" fill="${mut}" text-anchor="middle" font-family="Inter,sans-serif">Power SPV route · scope to agree</text>
   <text x="590" y="136" font-size="11.5" fill="${gh}" text-anchor="middle" font-family="Inter,sans-serif">modelled loss · ${pct(M.wind.lineLoss,1)} wind · ${pct(M.solar.lineLoss,1)} solar</text></g>
  <g class="fSeg fN-batt">${box(452,190,248,52,`${fmt(M.battery.powerMW,0)} MW storage scenario`,`${fmt(M.battery.powerMW*M.battery.durationH/1000,1)} GWh · ${fmt(M.battery.durationH,0)} h · ${pct(M.battery.socFloor,0)} reserve floor`,line,bat,GLY.batt)}</g>
  <g class="fNode fSeg fN-dc"><rect x="858" y="46" width="294" height="122" rx="12" fill="#16211c" stroke="${g}" stroke-width="1.6"/>
   <rect x="858" y="46" width="4" height="122" rx="2" fill="${g}"/>
   <g transform="translate(874,60)">${GLY.dc}</g>
   <text x="904" y="78" font-size="17" font-weight="640" fill="#fff" font-family="Inter,sans-serif">${fmt(M.dc.firmMW,0)} MW target campus</text>
   <text x="878" y="101" font-size="12.5" fill="${mut}" font-family="Inter,sans-serif">target load · phasing and SLA to be agreed</text>
   <text x="878" y="124" font-size="12.5" fill="${mut}" font-family="Inter,sans-serif">${fmt(M.dc.firmMW*8.76,0)} GWh of demand</text>
   <text x="878" y="147" font-size="12.5" fill="${gh}" font-family="Inter,sans-serif">Nickelsdorf, Burgenland</text></g>
 </svg>`;
}
