 const m=document.getElementById('main');
 if(gateLocked(active)){m.innerHTML=gatePage(active);postRender();setTimeout(gateAnimate,0);setTimeout(()=>{const e=document.getElementById('gatePw');if(e)e.focus();},60);return;}
 if(active==='overview'){m.innerHTML=overviewPage();}
 else if(active==='wind'){m.innerHTML=assetPage('wind');if(M.v3.wind&&assetView.wind==='tech')setTimeout(()=>start3d('wind'),0);}
 else if(active==='solar'){m.innerHTML=assetPage('solar');if(M.v3.solar&&assetView.solar==='tech')setTimeout(()=>start3d('solar'),0);}
 else if(active==='battery'){active='summary';spvView='batt';buildNav();m.innerHTML=summaryPage();}
 else if(active==='datacentre'){m.innerHTML=dcPage();}
 else if(active==='summary'){m.innerHTML=summaryPage();
  if(spvView==='fin'){setTimeout(drawSpvEcon,0);setTimeout(drawSpvCashflow,0);}
  else if(spvView==='supply')setTimeout(drawRisk,0);
  else if(spvView==='corr')setTimeout(drawCorrAll,0);
  else if(spvView==='tech'&&M.v3.battery)setTimeout(()=>start3d('battery'),0);}
 else if(active==='prices')m.innerHTML=pricesPage();
